from rules import resolve


def solve(data):
    return resolve(data)

def resolve(data):
    packages = data["packages"]
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    names = sorted(packages)

    if any(name not in packages for name in roots):
        return {"error": "unsatisfiable"}

    def active_deps(row):
        for dep in row.get("deps", []):
            feature = dep.get("feature")
            if feature and feature not in features:
                continue
            yield dep

    def is_acyclic(assigned):
        outgoing = {name: [] for name in assigned}
        indegree = {name: 0 for name in assigned}
        for name, row_index in assigned.items():
            row = packages[name][row_index]
            for dep in active_deps(row):
                dep_name = dep["name"]
                if dep_name not in assigned:
                    return False
                outgoing[name].append(dep_name)
                indegree[dep_name] += 1

        ready = [name for name, degree in indegree.items() if degree == 0]
        processed = 0
        while ready:
            name = ready.pop()
            processed += 1
            for dep_name in outgoing[name]:
                indegree[dep_name] -= 1
                if indegree[dep_name] == 0:
                    ready.append(dep_name)
        return processed == len(assigned)

    required = {name: [(bounds[0], bounds[1])]
                for name, bounds in roots.items()}
    best_vector = None
    best_versions = None

    def search(assigned, constraints):
        nonlocal best_vector, best_versions

        unresolved = [name for name in constraints if name not in assigned]
        if not unresolved:
            if not is_acyclic(assigned):
                return
            versions = {
                name: packages[name][row_index]["version"]
                for name, row_index in assigned.items()
            }
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
            return

        name = min(unresolved)
        for row_index, row in enumerate(packages[name]):
            version = row["version"]
            if version in blocked.get(name, ()):
                continue
            if name in pins and version != pins[name]:
                continue
            if not all(low <= version <= high
                       for low, high in constraints[name]):
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = row_index
            next_constraints = {
                key: list(ranges) for key, ranges in constraints.items()
            }
            valid = True

            for dep in active_deps(row):
                dep_name = dep["name"]
                if dep_name not in packages:
                    valid = False
                    break
                ranges = next_constraints.setdefault(dep_name, [])
                ranges.append((dep["min"], dep["max"]))
                if dep_name in next_assigned:
                    dep_version = packages[dep_name][
                        next_assigned[dep_name]
                    ]["version"]
                    if not all(low <= dep_version <= high
                               for low, high in ranges):
                        valid = False
                        break

            if valid:
                search(next_assigned, next_constraints)

    search({}, required)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
